//! `agent-worker install <uuid> --server <address>`: what the one-line command runs after it has downloaded this program.
//!
//! The uuid is the install's id, generated by the server when the form was saved (it becomes this worker's id). The program
//! checks in with the server: that proves it can reach it (with a specific error for each way that can fail), takes the
//! link with a secret generated on this PC and receives everything else the form saved. A second PC running the same
//! command is refused. It then refuses a second install on this PC, creates the token, the `agent-worker` command on the
//! PATH and the per-user startup entry, starts the worker, registers it and waits until it is connected. Progress goes to
//! the server so the Fleet tab can show each step and the reason for a failure.
use crate::config::{self, default_config, Home};
use crate::ctl::local_health;
use crate::svc::{self, Kind, Svc};
use crate::util::{atomic_json, now_unix};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use serde_json::{json, Value};
use std::path::PathBuf;
use std::time::{Duration, Instant};

pub struct Options {
    pub uuid: String,
    pub server: String,
    pub port: u16,
    pub no_service: bool,
}

/// What the form saved, as the server hands it over.
pub struct Settings {
    pub name: String,
    pub slots: u64,
}

fn origin(options: &Options) -> String {
    options.server.trim_end_matches('/').to_string()
}

async fn report(options: &Options, step: &str, state: &str, message: &str) {
    let _ = reqwest::Client::new().post(format!("{}/install/{}/progress", origin(options), options.uuid)).json(&json!({"step": step, "state": state, "message": message})).timeout(Duration::from_secs(10)).send().await;
}

pub fn default_home() -> PathBuf {
    if cfg!(windows) {
        PathBuf::from(std::env::var("LOCALAPPDATA").unwrap_or_default()).join("AgentWorker")
    } else {
        PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".agent-worker")
    }
}

/// One worker per PC: a finished install, or the startup entry of one, means this must be an update or an uninstall.
pub fn existing_install(home: &Home) -> Option<String> {
    for candidate in [home.0.clone(), default_home()] {
        if candidate.join("installed.json").exists() {
            return Some(candidate.display().to_string());
        }
    }
    if cfg!(windows) {
        if let Ok((0, out, _)) = svc::run("schtasks", &["/Query", "/FO", "CSV", "/NH"]) {
            if let Some(line) = out.lines().find(|l| l.contains("AgentWorker-")) {
                return Some(format!("scheduled task {}", line.split(',').next().unwrap_or("").trim_matches('"').trim_start_matches('\\')));
            }
        }
    } else {
        let home_dir = std::env::var("HOME").unwrap_or_default();
        for (dir, ext) in [(".config/systemd/user", "service"), ("Library/LaunchAgents", "plist")] {
            if let Ok(entries) = std::fs::read_dir(PathBuf::from(&home_dir).join(dir)) {
                for entry in entries.flatten() {
                    let name = entry.file_name().to_string_lossy().to_string();
                    if name.starts_with("agent-worker-") && name.ends_with(ext) {
                        return Some(entry.path().display().to_string());
                    }
                }
            }
        }
    }
    None
}

/// The secret this PC uses to take the link: generated once and kept, so a retry on the same PC is recognized and another PC
/// running the same command is not.
fn claim_secret(home: &Home) -> Result<String, String> {
    let path = home.file("claim");
    if let Ok(existing) = std::fs::read_to_string(&path) {
        if existing.trim().len() >= 20 {
            return Ok(existing.trim().to_string());
        }
    }
    std::fs::create_dir_all(&home.0).map_err(|e| format!("Could not create {}: {e}", home.0.display()))?;
    let mut raw = uuid::Uuid::new_v4().as_bytes().to_vec();
    raw.extend(uuid::Uuid::new_v4().as_bytes());
    let secret = URL_SAFE_NO_PAD.encode(raw);
    std::fs::write(&path, &secret).map_err(|e| format!("Could not save the claim secret: {e}"))?;
    Ok(secret)
}

/// Say what is wrong when the server cannot be reached, in words that point at the fix.
fn explain_network(server: &str, error: &reqwest::Error) -> String {
    let mut chain = String::new();
    let mut source: Option<&dyn std::error::Error> = Some(error);
    while let Some(e) = source {
        chain.push_str(&format!("{e} | "));
        source = e.source();
    }
    let lower = chain.to_lowercase();
    let host = reqwest::Url::parse(server).ok().and_then(|u| u.host_str().map(String::from)).unwrap_or_else(|| server.to_string());
    let why = if error.is_timeout() || lower.contains("timed out") {
        format!("{server} did not answer in time. Check that the address is right, that this PC can route to it (VPN, network) and that no firewall drops the traffic.")
    } else if lower.contains("dns") || lower.contains("lookup") || lower.contains("no such host") || lower.contains("name or service not known") || lower.contains("not known") {
        format!("the name {host} does not resolve on this PC. Use an address this PC can reach: set the form's address field to an IP or a name this PC knows, then create a new link.")
    } else if lower.contains("refused") {
        format!("{server} refused the connection. The board is not running there, or it listens on another port, or a firewall rejects this PC.")
    } else if lower.contains("certificate") || lower.contains("tls") || lower.contains("ssl") || lower.contains("handshake") {
        format!("the secure connection to {server} failed ({}). This PC does not trust the server's certificate, or the address uses https where the server speaks http (or the reverse).", chain.split(" | ").next().unwrap_or(""))
    } else if lower.contains("unreachable") || lower.contains("no route") {
        format!("there is no network route to {server} from this PC.")
    } else {
        format!("{} ({})", chain.trim_end_matches(" | "), server)
    };
    format!("Cannot reach the server: {why}")
}

/// Check in with the server: proves the PC can reach it, claims the link and returns what the form saved.
async fn claim(options: &Options, secret: &str) -> Result<Value, String> {
    let body = json!({"claim": secret, "host_os": config::os_name(), "hostname": crate::sysmetrics::host_name().unwrap_or_default()});
    let response = reqwest::Client::new().post(format!("{}/install/{}/claim", origin(options), options.uuid)).json(&body).timeout(Duration::from_secs(20)).send().await
        .map_err(|e| explain_network(&options.server, &e))?;
    let status = response.status().as_u16();
    let text = response.text().await.unwrap_or_default();
    let parsed: Option<Value> = serde_json::from_str(&text).ok();
    match (status, parsed) {
        (200, Some(v)) if v["ok"] == true => Ok(v),
        (404, _) => Err("This install link is unknown, expired or already used. Create a new one in the Fleet tab and paste its command.".into()),
        (429, _) => Err("Too many wrong install links came from this PC; wait ten minutes or create a new link.".into()),
        (_, Some(v)) if v["error"].is_string() => Err(v["error"].as_str().unwrap().to_string()),
        (200, _) => Err(format!("{} answered, but not like an agent orchestration server. Check the address (it should be the board's address).", options.server)),
        (s, _) => Err(format!("The server answered HTTP {s}{}. If this is a 502 or 503 the board is running but its relay service is not: start the flow host on the coordinator.", if text.is_empty() { String::new() } else { format!(": {}", text.chars().take(200).collect::<String>()) })),
    }
}

/// Put this program in the install folder (the one-line command runs it from a temporary download).
fn install_self(home: &Home) -> Result<Option<PathBuf>, String> {
    let me = std::env::current_exe().map_err(|e| e.to_string())?;
    let target = home.exe();
    if me.canonicalize().ok() == target.canonicalize().ok() && target.exists() {
        return Ok(None);
    }
    std::fs::create_dir_all(&home.0).map_err(|e| format!("Could not create {}: {e}", home.0.display()))?;
    let part = home.file(&format!("{}.part", Home::exe_name()));
    std::fs::copy(&me, &part).map_err(|e| format!("Could not copy the worker to {}: {e}", home.0.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&part, std::fs::Permissions::from_mode(0o755)).map_err(|e| e.to_string())?;
    }
    std::fs::rename(&part, &target).map_err(|e| e.to_string())?;
    Ok(Some(me))
}

fn in_temp_dir(path: &std::path::Path) -> bool {
    let canon = |p: &std::path::Path| std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
    canon(path).starts_with(canon(&std::env::temp_dir()))
}

/// Remove the temporary download once the install is done (Windows cannot delete a running program, so a helper does it).
fn remove_download(path: PathBuf) {
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        let _ = std::process::Command::new("cmd").raw_arg(format!("/c ping -n 4 127.0.0.1 >nul & del /f /q \"{}\"", path.display())).creation_flags(crate::procutil::DETACHED_PROCESS | crate::procutil::CREATE_NEW_PROCESS_GROUP | crate::procutil::CREATE_NO_WINDOW).stdin(std::process::Stdio::null()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).spawn();
    }
    #[cfg(not(windows))]
    {
        let _ = std::fs::remove_file(path);
    }
}

/// Windows: remember the user's profile folders and PATH. A worker started at boot runs without the user's environment
/// (their PATH, where Codex, Claude Code and npm tools live, and their profile folders), so `run` restores it from here.
fn capture_profile(worker: &mut Value) {
    if cfg!(windows) {
        let mut profile = serde_json::Map::new();
        for key in ["PATH", "USERPROFILE", "APPDATA", "LOCALAPPDATA", "HOMEDRIVE", "HOMEPATH", "USERNAME", "USERDOMAIN", "TEMP", "TMP"] {
            if let Ok(value) = std::env::var(key) {
                profile.insert(key.into(), json!(value));
            }
        }
        worker["profile"] = Value::Object(profile);
    }
}

fn restrict_token(path: &std::path::Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600)).map_err(|e| e.to_string())
    }
    #[cfg(windows)]
    {
        let user = svc::run("whoami", &[]).map_err(|e| e.to_string())?.1.trim().to_string();
        let (code, _, err) = svc::run("icacls", &[&path.to_string_lossy(), "/inheritance:r", "/grant:r", &format!("{user}:(R,W)")]).map_err(|e| e.to_string())?;
        if code == 0 { Ok(()) } else { Err(format!("Could not restrict the token file to this user: {}", err.trim())) }
    }
}

fn install_cli(home: &Home, config: &mut Value) {
    #[cfg(windows)]
    {
        let entry = home.0.display().to_string();
        let script = format!("$e = [Environment]::GetEnvironmentVariable('Path','User'); $parts = if ($e) {{ $e -split ';' }} else {{ @() }}; if ($parts -notcontains '{0}') {{ [Environment]::SetEnvironmentVariable('Path', (($parts + '{0}') -join ';'), 'User') }}", entry.replace('\'', "''"));
        let _ = svc::run("powershell", &["-NoProfile", "-NonInteractive", "-Command", &script]);
        config["path_entry"] = json!(entry);
    }
    #[cfg(unix)]
    {
        let link = PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".local/bin/agent-worker");
        let _ = std::fs::create_dir_all(link.parent().unwrap());
        let _ = std::fs::remove_file(&link);
        if std::os::unix::fs::symlink(home.exe(), &link).is_ok() {
            config["cli_links"] = json!([link.display().to_string()]);
        }
    }
    let _ = (home, config);
}

pub async fn install(home: Home, options: Options) -> Result<(), String> {
    let step = std::sync::Mutex::new("check".to_string());
    let result = run(&home, &options, &step).await;
    if let Err(message) = &result {
        let at = step.lock().unwrap().clone();
        report(&options, &at, "failed", message.lines().next().unwrap_or(message)).await;
    }
    result
}

async fn run(home: &Home, options: &Options, step: &std::sync::Mutex<String>) -> Result<(), String> {
    let at = |name: &str, text: &str| {
        *step.lock().unwrap() = name.to_string();
        println!("==> {text}");
    };
    if uuid::Uuid::parse_str(&options.uuid).is_err() {
        return Err(format!("{:?} is not an install id: it is the uuid in the Fleet tab's install command", options.uuid));
    }
    at("check", "Checking this PC");
    #[cfg(unix)]
    if unsafe { libc::getuid() } == 0 {
        return Err("Run this as a normal user, not root or sudo: the worker installs for one user".into());
    }
    if let Some(found) = existing_install(home) {
        return Err(format!("A worker is already installed on this PC ({found}). Update it with: agent-worker update. Remove it with: agent-worker uninstall (then run this command again)."));
    }
    println!("==> Contacting the server {}", options.server);
    let secret = claim_secret(home)?;
    let given = claim(options, &secret).await?;
    let settings = Settings { name: given["name"].as_str().ok_or("The server did not name this PC")?.to_string(), slots: given["slots"].as_u64().unwrap_or(1) };
    println!("    this PC will be {} ({})", settings.name, options.uuid);
    report(options, "check", "running", "").await;
    let download = install_self(home)?;
    let uuid = options.uuid.clone();

    at("token", "Creating this PC's token");
    report(options, "token", "running", "").await;
    let token = {
        let mut raw = uuid::Uuid::new_v4().as_bytes().to_vec();
        raw.extend(uuid::Uuid::new_v4().as_bytes());
        URL_SAFE_NO_PAD.encode(raw)
    };
    let token_path = home.file("token");
    std::fs::write(&token_path, &token).map_err(|e| e.to_string())?;
    restrict_token(&token_path)?;
    let kind = if options.no_service { Kind::Process } else { Kind::detect() };
    let mut worker = default_config(&settings.name, &uuid, settings.slots, &options.server, options.port);
    worker["service"] = json!(kind.name());
    worker["unit"] = json!(svc::default_unit(&settings.name));
    capture_profile(&mut worker);
    install_cli(home, &mut worker);
    home.save_config(&worker).map_err(|e| e.to_string())?;
    let svc = Svc::from_config(Home(home.0.clone()), &worker);

    if options.no_service {
        atomic_json(&home.file("installed.json"), &json!({"name": settings.name, "uuid": uuid, "at": now_unix(), "service": "none"})).map_err(|e| e.to_string())?;
        println!("Installed in {} (no startup entry, not registered). Start it with: agent-worker start", home.0.display());
        return Ok(());
    }

    at("service", "Starting the worker");
    report(options, "service", "running", "").await;
    svc.install()?;
    svc.start()?;
    let deadline = Instant::now() + Duration::from_secs(40);
    loop {
        if local_health(home, &worker).await.is_some() {
            break;
        }
        if Instant::now() > deadline {
            return Err(format!("The worker did not start; see {}", home.file("worker.log").display()));
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
    }

    at("register", "Registering this PC with the server");
    report(options, "register", "running", "").await;
    let host = crate::sysmetrics::host_name().unwrap_or_else(|| "unknown".into());
    let reply = reqwest::Client::new().post(format!("{}/install/{}/complete", origin(options), options.uuid)).json(&json!({"token": token, "claim": secret, "hostname": host})).timeout(Duration::from_secs(30)).send().await.map_err(|e| format!("Could not reach the server to register: {e}"))?;
    let status = reply.status();
    let body = reply.text().await.unwrap_or_default();
    if !status.is_success() || !body.contains("\"ok\": true") && !body.contains("\"ok\":true") {
        return Err(format!("The server refused the registration: {body}"));
    }

    at("connect", "Waiting for the connection");
    report(options, "connect", "running", "").await;
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        let state = reqwest::Client::new().get(format!("{}/install/{}/state", origin(options), options.uuid)).timeout(Duration::from_secs(5)).send().await;
        if let Ok(response) = state {
            if response.json::<Value>().await.map(|v| v["connected"] == true).unwrap_or(false) {
                break;
            }
        }
        if Instant::now() > deadline {
            return Err(format!("Registered, but the worker is not connected yet; see {}", home.file("worker.log").display()));
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
    }
    atomic_json(&home.file("installed.json"), &json!({"name": settings.name, "uuid": uuid, "at": now_unix(), "service": kind.name(), "version": config::self_version()})).map_err(|e| e.to_string())?;
    // only a download in the temporary folder is removed: a program run from anywhere else is the user's own file
    if let Some(path) = download.filter(|p| in_temp_dir(p)) {
        remove_download(path);
    }
    println!();
    println!("Done. {} ({uuid}) is connected and starts again {}.", settings.name, if cfg!(windows) { "when you log in" } else { "when you log in (or at boot, with systemd lingering)" });
    println!("Manage it with: agent-worker status | stop | start | restart | update | uninstall | logs");
    Ok(())
}
